{
  "template": "trigger"
}

namespace gillespie;
table Settings { seed:ulong; synthesis:double; degradation:double; volume:double; runs:ulong; }
table Outputs { settings:Settings (required); }
root_type Outputs;

{
  "template": "input",
  "params": [
    {
      "name": "seed",
      "type": "uint64",
      "data": 1
    },
    {
      "name": "synthesis",
      "type": "double",
      "data": 2.0
    },
    {
      "name": "degradation",
      "type": "double",
      "data": 0.1
    },
    {
      "name": "volume",
      "type": "double",
      "data": 1.0
    },
    {
      "name": "runs",
      "type": "uint64",
      "data": 2000
    }
  ]
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "trajectories",
        "stationary",
        "scaling",
        "binding"
      ]
    }
  ]
}

namespace gillespie;
table Outputs { }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

{
  "language": "julia",
  "inputs": [
    {
      "name": "settings"
    }
  ],
  "params": [
    {
      "name": "shown_runs",
      "type": "uint64",
      "data": 8
    }
  ]
}

namespace gillespie;
table Stationary { mean:double; variance:double; fano:double; theory:double; se_mean:double; se_variance:double; se_fano:double; runs:ulong; }
table Outputs { stationary:Stationary (required); }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

{
  "language": "julia",
  "inputs": [
    {
      "name": "settings"
    }
  ]
}

namespace gillespie;
table Scaling { volumes:[double]; means:[double]; cvs:[double]; theory_cvs:[double]; runs:ulong; }
table Outputs { scaling:Scaling (required); }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

{
  "language": "julia",
  "inputs": [
    {
      "name": "settings"
    }
  ],
  "params": [
    {
      "name": "volumes",
      "type": "double[]",
      "data": [
        0.05,
        0.1,
        0.3,
        1,
        3,
        10,
        30
      ]
    },
    {
      "name": "shown_volumes",
      "type": "double[]",
      "data": [
        0.1,
        1,
        10
      ]
    }
  ]
}

namespace gillespie;
table Binding { totals:[long]; ssa:[double]; se:[double]; exact:[double]; ode:[double]; }
table Outputs { binding:Binding (required); }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

{
  "language": "julia",
  "inputs": [
    {
      "name": "settings"
    }
  ],
  "params": [
    {
      "name": "concentration",
      "type": "double",
      "data": 2.0
    },
    {
      "name": "on_rate",
      "type": "double",
      "data": 1.0
    },
    {
      "name": "off_rate",
      "type": "double",
      "data": 1.0
    },
    {
      "name": "volumes",
      "type": "double[]",
      "data": [
        1,
        2,
        5,
        10,
        20,
        50,
        100
      ]
    },
    {
      "name": "replicas",
      "type": "uint64",
      "data": 40
    }
  ]
}

namespace gillespie;
table Outputs { }
root_type Outputs;

{ pkgs, inputs, params }: {
  run = inputs.tsugumi.juliaCard { src = ./src; };
}

{
  "language": "julia",
  "inputs": [
    {
      "name": "stationary"
    },
    {
      "name": "scaling"
    },
    {
      "name": "binding"
    }
  ],
  "params": [
    {
      "name": "limit_sigma",
      "type": "double",
      "data": 4.0
    }
  ]
}
